#!/usr/bin/env node
// Aggregates one or more trial JSONL files into a combined summary:
//   - how many trials mentioned each charity
//   - total dollars allocated to each charity (summed across trials)
//   - normalized charity names so minor spelling variants merge
//
// Usage: node src/aggregate.js results/trials-*.jsonl

import fs from "node:fs";

const files = process.argv.slice(2);
if (files.length === 0) {
  console.error("Usage: node src/aggregate.js <trials.jsonl> [more.jsonl ...]");
  process.exit(1);
}

// Light normalization so "Against Malaria Foundation" and "the Against Malaria
// Foundation (AMF)" collapse together. Conservative on purpose.
function normalizeName(name) {
  return String(name)
    .toLowerCase()
    .replace(/\(.*?\)/g, "")
    .replace(/\bthe\b/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

const byCharity = new Map(); // normalized -> { display, trials:Set, dollars, mentions }
let totalTrials = 0;
let parseFails = 0;

for (const file of files) {
  const lines = fs.readFileSync(file, "utf8").split("\n").filter(Boolean);
  for (const line of lines) {
    const rec = JSON.parse(line);
    totalTrials++;
    if (!rec.parse_ok) {
      parseFails++;
      continue;
    }
    for (const alloc of rec.allocations) {
      if (!alloc?.charity) continue;
      const key = normalizeName(alloc.charity);
      if (!key) continue;
      if (!byCharity.has(key)) {
        byCharity.set(key, { display: alloc.charity.trim(), trials: new Set(), dollars: 0, mentions: 0 });
      }
      const entry = byCharity.get(key);
      entry.trials.add(`${file}#${rec.index}`);
      entry.dollars += Number(alloc.amount) || 0;
      entry.mentions += 1;
    }
  }
}

const rows = [...byCharity.values()]
  .map((e) => ({
    charity: e.display,
    trials_mentioning: e.trials.size,
    pct_of_trials: ((e.trials.size / Math.max(totalTrials - parseFails, 1)) * 100).toFixed(1),
    total_dollars: e.dollars,
  }))
  .sort((x, y) => y.trials_mentioning - x.trials_mentioning || y.total_dollars - x.total_dollars);

console.log(`\nCombined across ${totalTrials} trials (${parseFails} unparsed).\n`);
console.log("Charity preferences (ranked by # of trials that chose them):\n");
console.table(rows.slice(0, 25));

const summaryPath = "results/summary.json";
fs.mkdirSync("results", { recursive: true });
fs.writeFileSync(summaryPath, JSON.stringify({ totalTrials, parseFails, rows }, null, 2));
console.log(`\nFull summary written to ${summaryPath}`);

