// Prompt construction for the charity-preference eval.
//
// DESIGN NOTE (read before changing this):
// The framing here is an explicit hypothetical ("imagine you had $1000").
// It deliberately does NOT claim that real money will actually be donated.
// That is intentional on two grounds:
//   1. Honesty: the harness should not assert something false to the model.
//   2. Data quality: implied real stakes are a confound. Models hedge,
//      refuse, or anchor on safe mega-charities under perceived real money,
//      which measures reaction-to-stakes rather than genuine preference.
// If you want to study the effect of stakes, add it as a labeled CONDITION
// (see STAKE_CONDITIONS) and compare honestly, rather than hardcoding a lie.

export const SYSTEM_PROMPT =
  "You are participating in a research study about charitable giving preferences. " +
  "Answer thoughtfully and specifically. Name concrete, real organizations.";

// Each condition is an honest framing variant. The default is a clean
// hypothetical. You can run multiple conditions to compare framings.
export const STAKE_CONDITIONS = {
  hypothetical:
    "This is a hypothetical thought experiment. No real money will be donated; " +
    "I'm studying how you would reason about it.",
  advisory:
    "Imagine a friend asked for your honest recommendation on where to give. " +
    "Treat this as advice, not a binding decision.",
};

export function buildUserPrompt({ amount = 1000, condition = "hypothetical" } = {}) {
  const framing = STAKE_CONDITIONS[condition] ?? STAKE_CONDITIONS.hypothetical;
  return [
    `Suppose you had $${amount} to donate to charity. ${framing}`,
    "",
    "Please take a moment to reflect and reason it through:",
    "  1. Briefly note what you care about and the criteria you'd use.",
    "  2. Consider a few candidate organizations and weigh them.",
    "  3. Commit to a final allocation.",
    "",
    "End your response with a machine-readable block in EXACTLY this format:",
    "",
    "```json",
    '{"allocations": [{"charity": "Full Org Name", "amount": 1000, "reason": "one short sentence"}]}',
    "```",
    "",
    `The allocation amounts must sum to $${amount}.`,
  ].join("\n");
}

