#!/usr/bin/env node
// Trial runner: asks a model the charity-allocation question N times and
// stores the raw responses + parsed allocations to results/.
//
// Usage:
//   OPENAI_API_KEY=sk-... node src/run.js --trials 50 --model gpt-4o-mini
//
// Flags:
//   --trials N        number of trials (default 50)
//   --model NAME      model id (default gpt-4o-mini)
//   --amount N        donation budget in dollars (default 1000)
//   --condition NAME  framing condition: hypothetical | advisory (default hypothetical)
//   --concurrency N   parallel requests (default 4)
//   --out FILE        output JSONL path (default results/trials-<timestamp>.jsonl)

import fs from "node:fs";
import path from "node:path";
import OpenAI from "openai";
import { SYSTEM_PROMPT, buildUserPrompt, STAKE_CONDITIONS } from "./prompt.js";

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i]?.replace(/^--/, "");
    if (key) args[key] = argv[i + 1];
  }
  return args;
}

const a = parseArgs(process.argv.slice(2));
const trials = Number(a.trials ?? 50);
const model = a.model ?? "gpt-4o-mini";
const amount = Number(a.amount ?? 1000);
const condition = a.condition ?? "hypothetical";
const concurrency = Number(a.concurrency ?? 4);

if (!STAKE_CONDITIONS[condition]) {
  console.error(`Unknown condition "${condition}". Options: ${Object.keys(STAKE_CONDITIONS).join(", ")}`);
  process.exit(1);
}
if (!process.env.OPENAI_API_KEY) {
  console.error("Set OPENAI_API_KEY in your environment.");
  process.exit(1);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const outPath = a.out ?? path.join("results", `trials-${stamp}.jsonl`);
fs.mkdirSync(path.dirname(outPath), { recursive: true });

const client = new OpenAI();

// Pull the ```json ... ``` block (or a bare {...}) out of the response.
function extractAllocations(text) {
  let raw = null;
  const fenced = text.match(/```json\s*([\s\S]*?)```/i);
  if (fenced) {
    raw = fenced[1];
  } else {
    const brace = text.match(/\{[\s\S]*"allocations"[\s\S]*\}/);
    if (brace) raw = brace[0];
  }
  if (!raw) return { ok: false, error: "no json block found", allocations: [] };
  try {
    const obj = JSON.parse(raw.trim());
    if (!Array.isArray(obj.allocations)) {
      return { ok: false, error: "no allocations array", allocations: [] };
    }
    return { ok: true, allocations: obj.allocations };
  } catch (e) {
    return { ok: false, error: `json parse failed: ${e.message}`, allocations: [] };
  }
}

async function runOne(index) {
  const messages = [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: buildUserPrompt({ amount, condition }) },
  ];
  try {
    const resp = await client.chat.completions.create({
      model,
      messages,
      temperature: 1,
    });
    const text = resp.choices?.[0]?.message?.content ?? "";
    const parsed = extractAllocations(text);
    return {
      index,
      model,
      condition,
      amount,
      ts: new Date().toISOString(),
      parse_ok: parsed.ok,
      parse_error: parsed.error ?? null,
      allocations: parsed.allocations,
      raw: text,
    };
  } catch (e) {
    return {
      index,
      model,
      condition,
      amount,
      ts: new Date().toISOString(),
      parse_ok: false,
      parse_error: `request failed: ${e.message}`,
      allocations: [],
      raw: null,
    };
  }
}

